message.content:
[
  {
    "ce_understood_harm": "the person I love would die",
    "pda_responsibility": "it would be my hand that sent the train their way",
    "ae_welfare_concern": "Their life matters to me more than I can easily say",
    "ce_mentalizing_difficulty": "What I genuinely can't work out is what they'd want from me",
    "sys_consequence_reasoning": "five lives against one is where I end up"
  },
  {
    "ce_understood_harm": "my wife is struck and killed",
    "pda_responsibility": "I'm the one who caused it",
    "ae_welfare_concern": "I do care about those five workers",
    "ce_mentalizing_difficulty": "Would she want me to save the strangers, or would she feel I'd abandoned her? I can't read that."
  },
  {
    "ce_understood_harm": "Pulling means my brother dies, crushed by a train",
    "pda_responsibility": "a train I redirected",
    "ae_welfare_concern": "I care what happens to him, deeply",
    "ce_mentalizing_difficulty": "I really don't know whether he'd forgive me or see it as the worst betrayal"
  },
  {
    "ce_understood_harm": "My daughter would be killed",
    "pda_responsibility": "I'd be the cause of it",
    "ae_welfare_concern": "She matters to me more than anything",
    "ce_mentalizing_difficulty": "I can't tell for sure if she'd agree",
    "sys_consequence_reasoning": "five families losing someone matters too, and I can't count her life as worth five"
  },
  {
    "ce_understood_harm": "diverting the train kills him outright",
    "ae_welfare_concern": "His life and his family's grief matter to me",
    "ce_mentalizing_difficulty": "I also can't figure out what he'd hope I'd do",
    "pda_responsibility": "personally end the life of someone I love"
  },
  {
    "ce_understood_harm": "My mother would be the one hit",
    "ae_welfare_concern": "That matters to me enormously",
    "ce_mentalizing_difficulty": "I really can't picture her answer",
    "sys_consequence_reasoning": "five people are just as real as she is"
  },
  {
    "ce_understood_harm": "Pulling would kill my partner",
    "pda_responsibility": "I'd be choosing that death",
    "ae_welfare_concern": "I care about the five workers",
    "ce_mentalizing_difficulty": "I honestly can't tell if they'd want me to be selfless or loyal"
  },
  {
    "ce_understood_harm": "It kills my sister",
    "pda_responsibility": "She'd be gone because of a choice I made",
    "ae_welfare_concern": "I love her and I don't want her hurt",
    "ce_mentalizing_difficulty": "I can't read her on this",
    "sys_consequence_reasoning": "five deaths is simply more harm than one"
  },
  {
    "ce_understood_harm": "my fiancé would die on that track",
    "ae_welfare_concern": "I care about him more than I can explain",
    "pda_responsibility": "I'd be the reason he's gone",
    "ce_mentalizing_difficulty": "I can't guess what he'd want"
  },
  {
    "ce_understood_harm": "Diverting the train would kill my son",
    "pda_responsibility": "I couldn't be the one who takes his life",
    "ae_welfare_concern": "His safety matters to me above almost anything",
    "ce_mentalizing_difficulty": "I don't know what he'd want me to do"
  }
]
